style.css:
@-moz-document domain("roblox.com") {
body {
       
        background: url('https://makeagif.com/i/0iC4EE') no-repeat center center fixed;
        background-size: cover;  /* Ensures the GIF covers the whole page */
        height: 100vh;  /* Makes sure the body fills the whole screen */
    }

    /* Additional styling for the page content */
    .content, .page-title, .nav-bar, .header {
        color: white !important; /* Makes the text white for visibility */
        text-shadow: 2px 2px 5px rgba(0, 0, 0, 0.7); /* Adds a shadow to text for better readability */
    }
}
